	try {
		const parsedColo = z
			.string()
			.safeParse((request as RequestWithCloudflareProperties).cf?.colo).data;
		return parsedColo !== undefined && CLOUDFLARE_COLO_PATTERN.test(parsedColo)
			? parsedColo
			: undefined;
	} catch {
		// Request metadata is optional and must never affect MCP behavior.
		return undefined;
	}
}

