function authorizeErrorResponse(message: string, status: number): Response {
	return htmlResponse(
		`<!doctype html><html lang="en"><head><meta charset="utf-8">` +
			`<title>Authorization error</title></head>` +
			`<body><p>${escapeHtml(message)}</p></body></html>`,
