import type {
	AuthRequest,
	OAuthHelpers,
} from "@cloudflare/workers-oauth-provider";
import {
	afterAll,
	afterEach,
	beforeAll,
	beforeEach,
	describe,
	expect,
	it,
	vi,
} from "vitest";
import { z } from "zod";
import { HevyHttpError } from "@hevy-mcp/hevy-client";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import {
	decodeAuthRequest,
	encodeAuthRequest,
	handleAuthorizeGet,
	handleAuthorizePost,
	hasOAuthAccessTokenFormat,
	renderAuthorizePage,
	type HevyOAuthDependencies,
} from "./worker-oauth.js";
import { createWorkerFetchHandler } from "./worker.js";
import { resetMemoryValidationCacheForTests } from "./validation-cache.js";
import {
	initializeMessage,
	jsonPostRequest,
	parseMcpResponse,
} from "./test-fixtures/mcp.js";

const OAUTH_RESOURCE = "https://mcp.hevy-mcp.dev/mcp";

class TestExecutionSpan implements Span {
	get isTraced(): boolean {
		return false;
	}

	/** Workers `Span` requires a span context; the test span stays inert. */
	spanContext(): TracingSpanContext {
		return { traceId: "", spanId: "", traceFlags: 0 };
	}

	setAttribute(_key: string, _value: boolean | number | string): this {
		return this;
	}

	setAttributes(
		_attributes: Record<string, boolean | number | string | undefined>,
	): this {
		return this;
	}

	recordException(_exception: Parameters<Span["recordException"]>[0]): void {}

	updateName(_name: string): this {
		return this;
	}

	setStatus(_status: TracingSpanStatus): this {
		return this;
	}

	end(): void {}
}

function createTestExecutionContext() {
	return {
		waitUntil(_promise: Promise<unknown>): void {},
		passThroughOnException(): void {},
		abort(_reason?: string): void {},
		mapVirtualHost(_fetcher: Fetcher, _port: number): string {
			throw new Error("mapVirtualHost is not used by these tests");
		},
		exports: {},
		props: {},
		tracing: {
			enterSpan<T, A extends unknown[]>(
				_name: string,
				callback: (span: Span, ...args: A) => T,
				...args: A
			): T {
				return callback(new TestExecutionSpan(), ...args);
			},
			startActiveSpan<T, A extends unknown[]>(
				_name: string,
				callback: (span: Span, ...args: A) => T,
				...args: A
			): T {
				return callback(new TestExecutionSpan(), ...args);
			},
			startSpan(_name: string): Span {
				return new TestExecutionSpan();
			},
			getActiveSpan(): Span | undefined {
				return undefined;
			},
			Span: TestExecutionSpan,
		},
	} satisfies ExecutionContext;
}

let testExecutionContext = createTestExecutionContext();

const originalRetryDelays = process.env.HEVY_VALIDATION_RETRY_DELAYS_MS;

beforeAll(() => {
	process.env.HEVY_VALIDATION_RETRY_DELAYS_MS = "1,2";
});

afterAll(() => {
	if (originalRetryDelays === undefined) {
		delete process.env.HEVY_VALIDATION_RETRY_DELAYS_MS;
	} else {
		process.env.HEVY_VALIDATION_RETRY_DELAYS_MS = originalRetryDelays;
	}
});

beforeEach(() => {
	testExecutionContext = createTestExecutionContext();
	vi.stubGlobal("Cloudflare", {
		compatibilityFlags: { global_fetch_strictly_public: true },
	});
});

afterEach(() => {
	vi.unstubAllGlobals();
	vi.restoreAllMocks();
	resetMemoryValidationCacheForTests();
});

const stringSchema = z.string();
type MemoryGetOptions = { readonly type?: string };
type TestOAuthEnv = typeof testExecutionContext;

function isString(
	value: string | MemoryGetOptions | undefined,
): value is string {
	return stringSchema.safeParse(value).success;
}

function createMockClient(overrides: Partial<HevyClient> = {}): HevyClient {
	return {
		getUserInfo: vi.fn().mockResolvedValue({ data: { id: "user" } }),
		...overrides,
	} as HevyClient;
}

const sampleAuthRequest: AuthRequest = {
	responseType: "code",
	clientId: "client-123",
	redirectUri: "https://claude.ai/api/mcp/auth_callback",
	scope: [],
	state: "state-xyz",
	resource: OAUTH_RESOURCE,
	codeChallenge: "challenge",
	codeChallengeMethod: "S256",
};

type FakeHelpers = Pick<
	OAuthHelpers,
	"parseAuthRequest" | "lookupClient" | "completeAuthorization"
>;

function createFakeHelpers(overrides: Partial<FakeHelpers> = {}): OAuthHelpers {
	const helpers: FakeHelpers = {
		parseAuthRequest: vi.fn().mockResolvedValue(sampleAuthRequest),
		lookupClient: vi.fn().mockResolvedValue({
			clientId: "client-123",
			clientName: "Claude",
			redirectUris: [sampleAuthRequest.redirectUri],
			tokenEndpointAuthMethod: "none",
		}),
		completeAuthorization: vi.fn().mockResolvedValue({
			redirectTo: `${sampleAuthRequest.redirectUri}?code=abc&state=state-xyz`,
		}),
		...overrides,
	};
	return helpers as OAuthHelpers;
}

function createDependencies(
	overrides: Partial<HevyOAuthDependencies<TestOAuthEnv>> = {},
): HevyOAuthDependencies<TestOAuthEnv> {
	return {
		validateApiKey: vi.fn().mockResolvedValue("valid"),
		serveMcp: vi.fn().mockResolvedValue(new Response("ok")),
		...overrides,
	};
}

function tokenPostRequest(fields: Record<string, string>): Request {
	return new Request("https://worker.example/token", {
		method: "POST",
		body: new URLSearchParams(fields),
	});
}

function registerRequest(
	body: Parameters<typeof jsonPostRequest>[0],
	headers: RequestInit["headers"] = { "content-type": "application/json" },
): Request {
	return jsonPostRequest(body, headers, "https://worker.example/register");
}

function authorizePostRequest(
	fields: Record<string, string>,
	signal?: AbortSignal,
): Request {
	return new Request("https://worker.example/authorize", {
		method: "POST",
		body: new URLSearchParams(fields),
		signal,
	});
}

function authorizeWithApiKey(apiKey: string, signal?: AbortSignal): Request {
	return authorizePostRequest(
		{
			oauth_request: encodeAuthRequest(sampleAuthRequest),
			hevy_api_key: apiKey,
		},
		signal,
	);
}

